export const CUES = [{"t": 3.6, "end": 11.42, "lines": [{"t0": 3.6, "t1": 8.34, "text": "For millions of years, our ancestors lived as other animals do:"}, {"t0": 8.34, "t1": 12.02, "text": "when the sun went down, the day was over."}]}, {"t": 12.6, "end": 16.28, "lines": [{"t0": 12.6, "t1": 16.88, "text": "Then someone, somewhere, learned to keep a fire alive."}]}, {"t": 29.6, "end": 40.23, "lines": [{"t0": 29.6, "t1": 32.35, "text": "No one knows who, or when."}, {"t0": 32.21, "t1": 37.06, "text": "Burnt bone in a South African cave hints at fire a million years ago,"}, {"t0": 37.06, "t1": 40.83, "text": "though everyday use may have come much later."}]}, {"t": 47.6, "end": 52.31, "lines": [{"t0": 47.6, "t1": 49.75, "text": "Either way, for the first time,"}, {"t0": 49.75, "t1": 52.91, "text": "the day did not end when the sun did."}]}, {"t": 56.0, "end": 63.05, "lines": [{"t0": 56.0, "t1": 59.95, "text": "The oldest fossils of our own species, found in Morocco,"}, {"t0": 59.95, "t1": 63.65, "text": "are around three hundred thousand years old."}]}, {"t": 64.4, "end": 75.29, "lines": [{"t0": 64.4, "t1": 71.79, "text": "From Africa, people spread across the world: by sea to Australia at least fifty thousand years ago,"}, {"t0": 71.79, "t1": 75.89, "text": "and into the Americas before the Ice Age ended."}]}, {"t": 78.4, "end": 88.98, "lines": [{"t0": 78.4, "t1": 80.52, "text": "On a cave wall in Indonesia,"}, {"t0": 80.52, "t1": 86.8, "text": "someone left the outline of a hand at least sixty-seven thousand years ago."}, {"t0": 86.66, "t1": 89.58, "text": "It is the oldest cave art we know."}]}, {"t": 92.6, "end": 100.12, "lines": [{"t0": 92.6, "t1": 95.58, "text": "Starting around eleven thousand years ago,"}, {"t0": 95.58, "t1": 100.72, "text": "in several parts of the world, separately, people began to farm."}]}, {"t": 101.6, "end": 113.85, "lines": [{"t0": 101.6, "t1": 104.72, "text": "Wheat and barley in the Middle East."}, {"t0": 104.58, "t1": 107.47, "text": "Rice and millet in China."}, {"t0": 107.33, "t1": 109.66, "text": "Maize in Mexico."}, {"t0": 109.52, "t1": 112.31, "text": "Potatoes in the Andes."}, {"t0": 112.17, "t1": 114.45, "text": "Sorghum in Africa."}]}, {"t": 115.4, "end": 120.79, "lines": [{"t0": 115.4, "t1": 117.43, "text": "It was hard work."}, {"t0": 117.29, "t1": 121.39, "text": "But a field can feed far more people than a forest."}]}, {"t": 122.6, "end": 126.53, "lines": [{"t0": 122.6, "t1": 127.13, "text": "Villages became towns, and towns became cities."}]}, {"t": 127.4, "end": 134.24, "lines": [{"t0": 127.4, "t1": 131.23, "text": "Five thousand years ago, Uruk, in what is now Iraq,"}, {"t0": 131.23, "t1": 134.84, "text": "was home to tens of thousands of people."}]}, {"t": 137.0, "end": 139.32, "lines": [{"t0": 137.0, "t1": 139.92, "text": "And here, people began to write."}]}, {"t": 145.0, "end": 151.86, "lines": [{"t0": 145.0, "t1": 148.06, "text": "The first writing wasn't poetry."}, {"t0": 147.92, "t1": 152.46, "text": "It was accounts: barley, beer, sheep, and who owed what."}]}, {"t": 152.8, "end": 160.19, "lines": [{"t0": 152.8, "t1": 156.17, "text": "Writing was invented at least three times,"}, {"t0": 156.17, "t1": 160.79, "text": "independently: here, in China, and in Mesoamerica."}]}, {"t": 161.6, "end": 166.95, "lines": [{"t0": 161.6, "t1": 165.67, "text": "At about the same time, someone made the first wheel."}, {"t0": 165.53, "t1": 167.55, "text": "We don't know who."}]}, {"t": 170.6, "end": 178.6, "lines": [{"t0": 170.6, "t1": 176.34, "text": "Empires rose and fell, and roads and sea lanes carried silk and spices,"}, {"t0": 176.34, "t1": 179.2, "text": "horses and glass, and ideas."}]}, {"t": 179.4, "end": 191.67, "lines": [{"t0": 179.4, "t1": 183.1, "text": "Buddhism travelled from India to China."}, {"t0": 182.96, "t1": 186.25, "text": "Paper went from China to Baghdad."}, {"t0": 186.11, "t1": 189.2, "text": "And the numerals we still use, born in India,"}, {"t0": 189.2, "t1": 192.27, "text": "reached Europe through Arabic books."}]}, {"t": 194.6, "end": 204.62, "lines": [{"t0": 194.6, "t1": 196.33, "text": "Far out in the Pacific,"}, {"t0": 196.33, "t1": 205.22, "text": "navigators reading the stars and the swell found and settled almost every island in the widest ocean on Earth."}]}, {"t": 207.6, "end": 219.5, "lines": [{"t0": 207.6, "t1": 212.91, "text": "Printing began in China, and movable type in China and Korea."}, {"t0": 212.77, "t1": 214.71, "text": "In Europe, around 1450,"}, {"t0": 214.71, "t1": 220.1, "text": "Gutenberg's press met an alphabet of a few dozen letters."}]}, {"t": 221.0, "end": 224.63, "lines": [{"t0": 221.0, "t1": 223.1, "text": "Books multiplied."}, {"t0": 222.96, "t1": 225.23, "text": "So did arguments."}]}, {"t": 227.0, "end": 233.08, "lines": [{"t0": 227.0, "t1": 228.3, "text": "In Italian cities,"}, {"t0": 228.3, "t1": 233.68, "text": "artists and engineers studied the ancient world, and the real one."}]}, {"t": 234.0, "end": 240.77, "lines": [{"t0": 234.0, "t1": 237.62, "text": "They learned to paint depth, drew the body from life,"}, {"t0": 237.62, "t1": 241.37, "text": "and raised the largest dome since Roman times."}]}, {"t": 248.6, "end": 255.52, "lines": [{"t0": 248.6, "t1": 252.4, "text": "In 1492, European ships reached the Americas,"}, {"t0": 252.4, "t1": 256.12, "text": "and two halves of the world collided."}]}, {"t": 256.8, "end": 271.79, "lines": [{"t0": 256.8, "t1": 261.29, "text": "Maize and potatoes went on to feed much of the world."}, {"t0": 261.15, "t1": 266.5, "text": "But diseases from Europe killed a large share of the people of the Americas,"}, {"t0": 266.5, "t1": 272.39, "text": "and over twelve million Africans were forced across the Atlantic in chains."}]}, {"t": 275.0, "end": 281.63, "lines": [{"t0": 275.0, "t1": 279.05, "text": "In 1610, Galileo turned a telescope on Jupiter,"}, {"t0": 279.05, "t1": 282.23, "text": "and saw moons going around it."}]}, {"t": 283.0, "end": 288.64, "lines": [{"t0": 283.0, "t1": 285.89, "text": "Science was a new habit: look carefully,"}, {"t0": 285.89, "t1": 289.24, "text": "test the idea, and trust the evidence."}]}, {"t": 292.6, "end": 304.06, "lines": [{"t0": 292.6, "t1": 298.16, "text": "In the 1700s, a bold idea spread through coffeehouses and pamphlets:"}, {"t0": 298.16, "t1": 304.66, "text": "that ordinary people could reason for themselves, and govern themselves."}]}, {"t": 305.4, "end": 314.07, "lines": [{"t0": 305.4, "t1": 309.63, "text": "Revolutions followed: in America, in France, and in Haiti,"}, {"t0": 309.63, "t1": 314.67, "text": "where enslaved people won their freedom and founded a nation."}]}, {"t": 318.4, "end": 325.13, "lines": [{"t0": 318.4, "t1": 321.48, "text": "Then steam engines turned coal into motion,"}, {"t0": 321.48, "t1": 325.73, "text": "and factories and railways spread across the world."}]}, {"t": 326.6, "end": 333.54, "lines": [{"t0": 326.6, "t1": 331.11, "text": "The telegraph carried words across oceans in minutes."}, {"t0": 330.97, "t1": 334.14, "text": "The camera could hold a moment for ever."}]}, {"t": 336.8, "end": 349.75, "lines": [{"t0": 336.8, "t1": 341.01, "text": "And with medicine, ordinary lives began to change."}, {"t0": 340.87, "t1": 341.53, "text": "In 1800,"}, {"t0": 341.53, "t1": 347.03, "text": "more than four in ten children died before the age of five."}, {"t0": 346.89, "t1": 350.35, "text": "Today, fewer than one in twenty do."}]}, {"t": 355.4, "end": 357.35, "lines": [{"t0": 355.4, "t1": 357.95, "text": "And then, the night changed."}]}, {"t": 368.8, "end": 375.8, "lines": [{"t0": 368.8, "t1": 370.66, "text": "Electricity."}, {"t0": 370.52, "t1": 372.67, "text": "Light at the flick of a switch,"}, {"t0": 372.67, "t1": 376.4, "text": "and power carried by wire to almost anywhere."}]}, {"t": 379.6, "end": 384.02, "lines": [{"t0": 379.6, "t1": 384.62, "text": "In 1903, a powered aeroplane flew for twelve seconds."}]}, {"t": 385.4, "end": 390.6, "lines": [{"t0": 385.4, "t1": 387.03, "text": "Cars filled the roads,"}, {"t0": 387.03, "t1": 391.2, "text": "and radio brought voices into millions of homes."}]}, {"t": 393.0, "end": 398.46, "lines": [{"t0": 393.0, "t1": 395.7, "text": "The same century fought two world wars,"}, {"t0": 395.7, "t1": 399.06, "text": "which killed tens of millions of people."}]}, {"t": 402.6, "end": 408.32, "lines": [{"t0": 402.6, "t1": 405.5, "text": "It also found antibiotics and vaccines,"}, {"t0": 405.5, "t1": 408.92, "text": "which have saved hundreds of millions."}]}, {"t": 410.4, "end": 415.19, "lines": [{"t0": 410.4, "t1": 413.41, "text": "And sixty-six years after that first flight,"}, {"t0": 413.41, "t1": 415.79, "text": "people walked on the Moon."}]}, {"t": 421.0, "end": 428.72, "lines": [{"t0": 421.0, "t1": 426.4, "text": "Today, most of the eight billion people alive carry a computer in their pocket,"}, {"t0": 426.4, "t1": 429.32, "text": "connected to nearly everyone else."}]}, {"t": 440.0, "end": 442.43, "lines": [{"t0": 440.0, "t1": 443.03, "text": "And that is everything, so far."}]}, {"t": 447.6, "end": 452.28, "lines": [{"t0": 447.6, "t1": 450.53, "text": "Ahead, the cardboard is still blank."}, {"t0": 450.39, "t1": 452.88, "text": "No one has cut it yet."}]}, {"t": 455.8, "end": 457.43, "lines": [{"t0": 455.8, "t1": 458.03, "text": "That part is up to us."}]}];
